--- tracked? ---
dab/mappings/customer-mapping.yaml
dab/mappings/order-mapping.yaml
--- ignore ---
# Python
__pycache__/
*.py[cod]
.venv/
.pytest_cache/
.ruff_cache/

# The warehouse is built, never committed. Everything in it is reproducible from
# das/fixtures via `uv run adss build --offline`.
*.duckdb
*.duckdb.wal

# dlt working state
.dlt/
~/.dlt/

# marimo drops a session cache next to the notebook on export
__marimo__/

# daana-cli writes here
logs/

# Screenshots are attached to a pull request, not committed.
.screenshots/

# The lake is derived from das/fixtures by `adss das ingest`. The recording is the
# committed artefact; the parquet it produces is not.
das/lake/
.browsers/

# Generated DAS view SQL. Unlike the DAR layer's, it embeds the lake's absolute path -- a
# relative one would resolve at query time, in whatever directory the reader happens to be --
# so it cannot be the same on two machines and is generated at build time instead of
# committed. The checks it also generates carry no path and ARE committed.
das/sql/

# The engine rewrites these from the YAML on every deploy. The YAML is the reviewed artefact;
# a committed copy of it would be a second place the data is explained.
dab/*.json
dab/mappings/*.json
--- json head ---
{
  "entity_id": "ORDER",
  "mapping_groups": [
    {
      "name": "default_mapping_group",
      "allow_multiple_identifiers": false,
      "tables": [
        {
          "connection": "dev",
          "table": "das__staged.orders",
          "primary_keys": [
            "order_id"
          ],
          "ingestion_strategy": "FULL_LOG",
          "effective_datetime": "extracted_at",
          "attributes": [
            {
              "id": "ORDER_NUMBER",
              "transformation_expression": "cast(order_id AS VARCHAR)"
            },
            {
              "id": "PLACED_ON",
              "transformation_expression": "order_date"
            },
            {
              "id": "DESTINATION_COUNTRY",
              "transformation_expression": "ship_country"
            },
            {
              "id": "FREIGHT_CHARGE",
              "transformation_expression": "freight"
            },
            {
              "id": "SHIPPED_ON",
              "transformation_expression": "shipped_date"
            },
            {
              "id": "SHIP_LAG_DAYS",
              "transformation_expression": "date_diff('day', order_date, shipped_date)"
            },
            {
              "id": "ORDER_DESTINATION_COUNTRY_EFF_TMSTP",
              "transformation_expression": "extracted_at"
            },
            {
              "id": "ORDER_FREIGHT_CHARGE_EFF_TMSTP",
              "transformation_expression": "extracted_at"
            },
            {
              "id": "ORDER_SHIP_LAG_DAYS_EFF_TMSTP",
              "transformation_expression": "extracted_at"
            }
          ]
        }
      ],
      "relationships": [
        {
          "atomic_context": "ORDER_IS_PLACED_BY_CUSTOMER",
          "source_table": "das__staged.orders",
          "target_transformation_expression": "customer_id"
        }
      ]
    }
  ],
  "template_model_source": "",
  "template_generated_at": ""
}
